import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";

import * as Item from "../../ui/item";

// MODEL
export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE
export const Message = m("Message");
export type Message = typeof Message.Type;

// INIT
export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE
export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({ Message: () => [model, []] })
  );

// VIEW
export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();
  return h.div(
    [h.Class("w-full")],
    [
      Item.groupView<Message>({
        children: [
          Item.view<Message>({
            children: [
              Item.mediaView<Message>({ variant: "avatar", children: ["s"] }),
              Item.contentView<Message>({
                children: [
                  Item.titleView<Message>({ children: ["shadcn"] }),
                  Item.descriptionView<Message>({
                    children: ["shadcn@vercel.com"],
                  }),
                ],
              }),
            ],
          }),
          Item.separatorView<Message>(),
          Item.view<Message>({
            children: [
              Item.mediaView<Message>({ variant: "avatar", children: ["m"] }),
              Item.contentView<Message>({
                children: [
                  Item.titleView<Message>({ children: ["maxleiter"] }),
                  Item.descriptionView<Message>({
                    children: ["maxleiter@vercel.com"],
                  }),
                ],
              }),
            ],
          }),
          Item.separatorView<Message>(),
          Item.view<Message>({
            children: [
              Item.mediaView<Message>({ variant: "avatar", children: ["e"] }),
              Item.contentView<Message>({
                children: [
                  Item.titleView<Message>({ children: ["evilrabbit"] }),
                  Item.descriptionView<Message>({
                    children: ["evilrabbit@vercel.com"],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("item-group example", () => {
  test("renders the shadcn Item Group example", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.text("shadcn")).not.toHaveHandler("click")
    );
  });
});
